import {createComputer} from './lab.js';
import {getSession,exportWorkspace,importWorkspace,download,PATHS} from './workspace-session.js';
const base=new URL('.',import.meta.url),url=p=>new URL(p,base);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const encoder=new TextEncoder();
const fmt=n=>Number(n||0).toLocaleString('en-US');
async function bytes(path){const r=await fetch(url(path));if(!r.ok)throw Error(`Could not load ${path} (${r.status})`);return new Uint8Array(await r.arrayBuffer());}
async function graph(){const data=await bytes('neural-circuit.json.gz');if(data[0]!==31||data[1]!==139)return JSON.parse(new TextDecoder().decode(data));const stream=new Blob([data]).stream().pipeThrough(new DecompressionStream('gzip'));return new Response(stream).json();}
function join(dir,name){return (dir==='/'?'':dir)+'/'+name;}
function describeSize(n){return n<1024?`${n} B`:n<1048576?`${(n/1024).toFixed(1)} KB`:`${(n/1048576).toFixed(2)} MB`;}
export function createWorkbench(api){
 if(!document.querySelector('#orbit-workbench-css')){const l=document.createElement('link');l.id='orbit-workbench-css';l.rel='stylesheet';l.href=url('workbench.css');document.head.append(l);}
 const root=document.createElement('div');root.className='orbit-workbench';
 root.innerHTML=`<nav class="ow-nav" aria-label="Machine workspace"><button data-view="cpu" class="active">Computer</button><button data-view="drive">Memory Drive</button><button data-view="vector">Vector unit</button><button data-view="model">Stories260K</button><span class="ow-spacer"></span><button class="ow-save" data-export>Export state ↓</button><button data-import>Import ↑</button><input type="file" accept=".orbit-state,.gz,.json,application/octet-stream" data-state-file hidden aria-label="Import saved Orbit state"></nav><div class="ow-body"><section class="ow-pane" data-pane="cpu"></section><section class="ow-pane" data-pane="drive" hidden></section><section class="ow-pane" data-pane="vector" hidden></section><section class="ow-pane" data-pane="model" hidden></section></div>`;
 const $=s=>root.querySelector(s);let s=getSession(),disposed=false,view='cpu',dir='/',selected=null,generating=false,stopGeneration=false,loadedUnit=null,operation=null,modelPrompt='Once upon a time',modelCount=64;
 const cpuView=createComputer(api);s.cpuView=cpuView;$('[data-pane="cpu"]').append(cpuView.element);
 function lock(value){operation=value;$('.ow-body').inert=!!value;for(const key of ['export','import'])$(`[data-${key}]`).disabled=!!value;}
 function status(message,error=false,pane=view){const target=$(`[data-pane="${pane}"] .ow-status`);if(target){target.textContent=message;target.classList.toggle('error',error);}if(error)api.toast(message);}
 async function getUnit(){if(loadedUnit)return loadedUnit;const {CompiledVectorUnit}=await import('./vector.js');loadedUnit=s.unit??new CompiledVectorUnit();s.unit=loadedUnit;return loadedUnit;}
 function switchView(next){view=next;for(const b of root.querySelectorAll('[data-view]'))b.classList.toggle('active',b.dataset.view===next);for(const p of root.querySelectorAll('[data-pane]'))p.hidden=p.dataset.pane!==next;if(next==='drive')renderDrive();if(next==='vector')renderVector();if(next==='model')renderModel();}
 for(const b of root.querySelectorAll('[data-view]'))b.onclick=()=>switchView(b.dataset.view);
 function renderDrive(){const pane=$('[data-pane="drive"]');pane.innerHTML=`<header class="ow-section"><div class="ow-title-row"><h1>Files with a state of their own.</h1><span class="ow-tag">RECURRENT MEMORY</span></div><p class="ow-sub">Names, directories, and file bytes live in Gated DeltaNet head matrices. Export this machine’s state, attach the file to a chat, and import it later to recover them.</p></header><div class="ow-toolbar"><button class="ow-button" data-up>↑</button><input class="ow-input ow-path" aria-label="Neural drive path" value="${esc(dir)}"><input class="ow-input" data-name aria-label="New file or folder name" placeholder="name.txt" style="width:130px"><button class="ow-button" data-new-file>+ File</button><button class="ow-button" data-new-folder>+ Folder</button><button class="ow-button" data-upload>Import file</button><button class="ow-button" data-memory-weights>Weights ↓</button><input type="file" data-upload-file hidden multiple></div><div class="ow-fs-main"><div class="ow-files"></div><section class="ow-file-editor"><div class="ow-file-title"><span data-file-label>Select a file</span><span style="flex:1"></span><button class="ow-button" data-file-save disabled>Save</button><button class="ow-button" data-file-download disabled>↓</button><button class="ow-button" data-file-delete disabled>Delete</button></div><textarea class="ow-textarea" aria-label="Neural file contents" placeholder="A space for something you want to keep." disabled></textarea></section></div><div class="ow-status" role="status"></div><footer class="ow-footer"><strong>${describeSize(s.fs.getStats().capacityBytes)} drive · ${s.fs.getStats().headCount} recurrent heads</strong><span>File contents and directory index are recurrent state.</span><span>Export state to preserve this workspace across chats or devices.</span></footer>`;
 const list=$('.ow-files');let entries;try{entries=s.fs.list(dir);}catch(error){dir='/';entries=s.fs.list(dir);$('.ow-path').value=dir;status(error.message,true,'drive');}
 list.innerHTML=entries.length?entries.map(entry=>{const path=entry.path??join(dir,entry.name);const folder=['dir','directory','folder'].includes(entry.type)||entry.isDirectory;return `<button class="ow-file ${selected===path?'active':''}" data-file-path="${esc(path)}" data-directory="${folder?'1':'0'}"><span class="ow-file-symbol">${folder?'▱':'▤'}</span><span>${esc(entry.name??path.split('/').pop())}</span><small>${folder?'Folder':describeSize(entry.size??entry.sizeBytes??0)}</small></button>`;}).join(''):'<div class="ow-empty">A little room for your next file.</div>';
 for(const b of root.querySelectorAll('[data-file-path]'))b.onclick=()=>{if(b.dataset.directory==='1'){dir=b.dataset.filePath;selected=null;renderDrive();}else{selected=b.dataset.filePath;showFile();for(const r of root.querySelectorAll('[data-file-path]'))r.classList.toggle('active',r===b);}};
 const navigate=()=>{try{s.fs.list($('.ow-path').value);dir=$('.ow-path').value;selected=null;renderDrive();}catch(e){status(e.message,true,'drive');}};$('.ow-path').onkeydown=e=>{if(e.key==='Enter')navigate();};$('[data-up]').onclick=()=>{dir=dir.split('/').slice(0,-1).join('/')||'/';selected=null;renderDrive();};
 function name(){const n=$('[data-name]').value.trim();if(!n||n.includes('/')||n==='.'||n==='..')throw Error('Enter a file or folder name without slashes.');return join(dir,n);}
 $('[data-new-file]').onclick=()=>{try{const p=name();if(s.fs.exists(p))throw Error('That name is already in use.');s.fs.writeFile(p,'');selected=p;renderDrive();showFile();}catch(e){status(e.message,true,'drive');}};
 $('[data-new-folder]').onclick=()=>{try{const p=name();if(s.fs.exists(p))throw Error('That name is already in use.');s.fs.mkdir(p);renderDrive();}catch(e){status(e.message,true,'drive');}};
 $('[data-memory-weights]').onclick=()=>download(encoder.encode(JSON.stringify(s.fs.exportCircuit())), 'orbit-memory-weights.json','application/json');
 $('[data-upload]').onclick=()=>$('[data-upload-file]').click();$('[data-upload-file]').onchange=async e=>{try{for(const file of e.target.files){s.fs.writeFile(join(dir,file.name),new Uint8Array(await file.arrayBuffer()));}renderDrive();status('Imported into recurrent memory.','', 'drive');}catch(error){status(error.message,true,'drive');}};
 $('[data-file-save]').onclick=()=>{try{s.fs.writeFile(selected,$('.ow-file-editor textarea').value);status('Saved in recurrent memory. Export the state to keep a durable copy.');}catch(e){status(e.message,true,'drive');}};
 $('[data-file-download]').onclick=()=>{if(selected)download(s.fs.readFile(selected),selected.split('/').pop());};
 $('[data-file-delete]').onclick=()=>{try{s.fs.delete(selected);selected=null;renderDrive();status('File removed from recurrent memory.');}catch(e){status(e.message,true,'drive');}};
 if(selected&&s.fs.exists(selected))showFile();
 }
 function showFile(){try{const data=s.fs.readFile(selected);let text='',binary=/\.(bin|gz|orbit-state)$/i.test(selected)||data.length>65536;if(!binary){try{text=new TextDecoder('utf-8',{fatal:true}).decode(data);binary=/[\x00-\x08\x0b\x0c\x0e-\x1f]/.test(text);}catch{binary=true;}}const editor=$('.ow-file-editor textarea');editor.disabled=false;editor.readOnly=binary;editor.value=binary?`Binary file · ${describeSize(data.length)}\n\nDownload this file to inspect it. It is stored in the same recurrent memory as your text files.`:text;$('[data-file-label]').textContent=selected;$('[data-file-save]').disabled=binary;$('[data-file-download]').disabled=false;$('[data-file-delete]').disabled=false;}catch(e){status(e.message,true,'drive');}}
 function renderVector(){const pane=$('[data-pane="vector"]');pane.innerHTML=`<section class="ow-section"><div class="ow-title-row"><h1>Arithmetic, compiled into a circuit.</h1><span class="ow-tag">NUMERICAL VECTOR EXTENSION</span></div><p class="ow-sub">Fixed weighted affine and multiplicative circuits compute matrix products, attention, and normalization. Softmax uses a compiled exponential approximation and Newton reciprocal iterations.</p><div class="ow-grid"><div class="ow-field"><label>MATRIX A</label><textarea class="ow-textarea" data-a aria-label="Matrix A">[[1,2,3],[4,5,6]]</textarea></div><div class="ow-field"><label>MATRIX B</label><textarea class="ow-textarea" data-b aria-label="Matrix B">[[1,0],[0,1],[1,1]]</textarea></div></div><div class="ow-vector-actions"><button class="ow-button primary" data-matmul>Matrix multiply</button><button class="ow-button" data-circuit>Download compiled weights ↓</button></div><pre class="ow-result" data-matrix-result>2 × 3 · 3 × 2 → 2 × 2</pre><div class="ow-field" style="margin-top:22px"><label>SOFTMAX LOGITS</label><input class="ow-input" data-logits aria-label="Softmax logits" value="[1,2,3]" style="width:100%"></div><div class="ow-vector-actions"><button class="ow-button" data-softmax>Run compiled softmax</button></div><pre class="ow-result" data-softmax-result>Probabilities will appear here.</pre><p class="ow-note">This is a numerical weighted-circuit extension, with exported SwiGLU emission metadata and error bounds. It is evaluated separately from the verified integer CPU. A full merged Qwen checkpoint with this vector unit has not been emitted or verified.</p><div class="ow-status" role="status"></div></section>`;
 $('[data-matmul]').onclick=async()=>{try{const A=JSON.parse($('[data-a]').value),B=JSON.parse($('[data-b]').value);if(!Array.isArray(A)||!Array.isArray(B)||!A.length||!B.length||!Array.isArray(A[0])||!Array.isArray(B[0]))throw Error('Enter two rectangular matrices.');const m=A.length,k=A[0].length,n=B[0].length;if(k!==B.length||Math.max(m,k,n)>32||!k||!n||A.some(r=>r.length!==k)||B.some(r=>r.length!==n)||![...A.flat(),...B.flat()].every(Number.isFinite))throw Error('Use compatible finite matrices with dimensions up to 32.');const unit=await getUnit(),out=unit.matmul(Float32Array.from(A.flat()),Float32Array.from(B.flat()),m,k,n);$('[data-matrix-result]').textContent=JSON.stringify(Array.from({length:m},(_,r)=>Array.from(out.slice(r*n,(r+1)*n))),null,2);status('Computed by the compiled weighted vector unit.');}catch(e){status(e.message,true,'vector');}};
 $('[data-softmax]').onclick=async()=>{try{const x=JSON.parse($('[data-logits]').value);if(!Array.isArray(x)||!x.length||x.length>512||!x.every(Number.isFinite))throw Error('Enter 1–512 finite logits.');const unit=await getUnit();$('[data-softmax-result]').textContent=JSON.stringify(Array.from(unit.softmax(Float32Array.from(x))),null,2);status('Compiled exponential and reciprocal circuits; no host Math.exp fallback.');}catch(e){status(e.message,true,'vector');}};
 $('[data-circuit]').onclick=async()=>{try{download(await bytes('vector-weights.json'),'orbit-vector-weights.json','application/json');}catch(e){status(e.message,true,'vector');}};
 }
 async function ensureModel(){if(s.model)return s.model;status('Loading published weights and placing them in Memory Drive…',false,'model');const unit=await getUnit();if(!s.fs.exists(PATHS.model))s.fs.writeFile(PATHS.model,await bytes('models/stories260K.bin'));if(!s.fs.exists(PATHS.tokenizer))s.fs.writeFile(PATHS.tokenizer,await bytes('models/tok512.bin'));const {Stories260K}=await import('./tiny-model.js');s.model=new Stories260K(s.fs.readFile(PATHS.model),s.fs.readFile(PATHS.tokenizer),{unit});if(s.fs.exists(PATHS.story))s.model.loadState(JSON.parse(s.fs.readText(PATHS.story)));return s.model;}
 function renderModel(){const pane=$('[data-pane="model"]');pane.innerHTML=`<section class="ow-section"><div class="ow-title-row"><h1>A tiny model. A real forward pass.</h1><span class="ow-tag">KARPATHY · STORIES260K</span></div><p class="ow-sub">The published TinyStories checkpoint and its 512-token tokenizer, running locally through the compiled vector circuits. Model files live in Memory Drive after loading.</p><div class="ow-facts"><div class="ow-fact"><label>PARAMETERS</label><strong>260,032</strong></div><div class="ow-fact"><label>TRANSFORMER LAYERS</label><strong>5</strong></div><div class="ow-fact"><label>QUERY / KV HEADS</label><strong>8 / 4</strong></div><div class="ow-fact"><label>CONTEXT</label><strong>512 tokens</strong></div></div><div class="ow-model-prompt ow-field"><label>PROMPT</label><textarea class="ow-textarea" data-prompt aria-label="Story prompt">${esc(modelPrompt)}</textarea></div><div class="ow-story-controls"><button class="ow-button primary" data-generate ${generating?'disabled':''}>Load & generate</button><button class="ow-button" data-resume ${s.model&&!generating?'':'disabled'}>Continue saved state</button><button class="ow-button" data-stop ${generating?'':'disabled'}>Stop</button><select class="ow-select" data-token-count aria-label="Tokens to generate">${[32,64,128].map(n=>`<option value="${n}" ${modelCount===n?'selected':''}>${n}</option>`).join('')}</select><span class="ow-model-state">Greedy decoding · deterministic</span></div><div class="ow-story" role="log" aria-live="polite">${esc(s.model?.text||'Your story will appear here.')}</div><div class="ow-story-controls"><button class="ow-button" data-save-story>Save story to Memory Drive</button><button class="ow-button" data-save-generation ${s.model?'':'disabled'}>Checkpoint generation</button></div><p class="ow-note">Small TinyStories model, not an instruction-following assistant. Its model weights and saved generation cache are serialized inside the recurrent filesystem. During inference, temporary vector buffers and KV working arrays live in browser memory; checkpointing commits the resumable state to Memory Drive. <a href="https://github.com/karpathy/llama2.c/blob/master/doc/stories260K.md" target="_blank" rel="noopener">Model source ↗</a></p><div class="ow-status" role="status"></div></section>`;
 $('[data-prompt]').oninput=e=>{modelPrompt=e.target.value;};$('[data-token-count]').onchange=e=>{modelCount=Number(e.target.value);};$('[data-generate]').onclick=()=>generate(false);$('[data-resume]').onclick=()=>generate(true);$('[data-stop]').onclick=()=>{stopGeneration=true;};$('[data-save-story]').onclick=()=>{try{const text=$('.ow-story').textContent;s.fs.writeFile('/documents/story.txt',text);status('Story saved in recurrent Memory Drive.');}catch(e){status(e.message,true,'model');}};$('[data-save-generation]').onclick=()=>checkpointModel();
 }
 function checkpointModel(){try{if(!s.model)throw Error('Load the model first.');if(generating)throw Error('Stop generation before checkpointing.');s.fs.writeFile(PATHS.story,JSON.stringify(s.model.getState()));status('Generation state committed to recurrent memory. Export state to resume in another chat.');}catch(e){status(e.message,true,'model');}}
 async function generate(resume){if(generating||operation||s.modelBusy)return;generating=true;s.modelBusy=true;stopGeneration=false;try{for(const key of ['generate','resume'])$(`[data-${key}]`).disabled=true;$('[data-stop]').disabled=false;const model=await ensureModel();if(!resume)model.begin($('[data-prompt]').value,{temperature:0,seed:42});const max=Number($('[data-token-count]').value)||modelCount;status('Running compiled matrix, attention, normalization, and softmax circuits…',false,'model');const started=performance.now();let result,produced=0,steps=0;while(produced<max&&steps<512&&!stopGeneration&&!disposed){result=model.step();steps++;if(!result.forced)produced++;if(view==='model')$('.ow-story').textContent=result.text??model.text??'';if(result.done)break;await new Promise(resolve=>setTimeout(resolve,0));}if(view==='model')status(`${stopGeneration?'Paused':'Finished'} · ${((performance.now()-started)/1000).toFixed(2)} s. Checkpoint or export state to preserve generation.`,false,'model');}catch(e){status(e.message,true,'model');}finally{generating=false;s.modelBusy=false;if(view==='model'){for(const key of ['generate','resume','save-generation'])$(`[data-${key}]`).disabled=false;$('[data-stop]').disabled=true;}}}
 $('[data-export]').onclick=async()=>{let owned=false;try{if(generating||operation)throw Error('Finish the current operation before exporting.');lock('export');owned=true;const data=await exportWorkspace(s);download(data,'Orbit-memory.orbit-state','application/octet-stream');api.toast('State exported. Attach that file to a chat to keep it.');}catch(e){api.toast(e.message);}finally{if(owned)lock(null);}};
 $('[data-import]').onclick=()=>$('[data-state-file]').click();$('[data-state-file]').onchange=async e=>{const file=e.target.files?.[0];if(!file)return;let owned=false;try{if(generating||operation)throw Error('Finish the current operation before importing.');lock('import');owned=true;cpuView.getMachine?.();const [circuit,unit,module]=await Promise.all([graph().catch(()=>null),getUnit().catch(()=>null),import('./tiny-model.js').catch(()=>null)]);const Stories260K=module?.Stories260K;const next=await importWorkspace(new Uint8Array(await file.arrayBuffer()),{circuit,unit,createModel:Stories260K&&unit?(model,tokenizer,u)=>new Stories260K(model,tokenizer,{unit:u}):undefined});s=next;s.cpuView=cpuView;if(next.restoredCpu)await cpuView.setMachine(next.restoredCpu);selected=null;dir='/';switchView('drive');api.toast(next.cpuError||next.modelError?'Files restored. Optional execution state could not resume: '+(next.cpuError||next.modelError):'Recurrent memory restored. Your files are back.');}catch(error){api.toast(error.message);}finally{e.target.value='';if(owned)lock(null);}};
 return {element:root,title:'Orbit · Memory, vectors & stories',destroy:()=>{disposed=true;stopGeneration=true;cpuView.destroy?.();s.cpuView=null;}};
}
